using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;using PokeMarketApi.Data;using PokeMarketApi.Services;var b=WebApplication.CreateBuilder(args);b.Services.AddControllersWithViews();b.Services.AddRazorPages();b.Services.AddDbContext<MarketContext>(o=>o.UseSqlite(b.Configuration.GetConnectionString("MarketDb")));b.Services.AddDefaultIdentity<IdentityUser>(o=>o.SignIn.RequireConfirmedAccount=false).AddEntityFrameworkStores<MarketContext>();b.Services.AddHttpClient<CatalogClient>(c=>c.BaseAddress=new Uri(b.Configuration["CatalogApi:BaseUrl"]??"https://localhost:7165/"));var app=b.Build();using(var s=app.Services.CreateScope()){s.ServiceProvider.GetRequiredService<MarketContext>().Database.EnsureCreated();}app.UseHttpsRedirection();app.UseStaticFiles();app.UseRouting();app.UseAuthentication();app.UseAuthorization();app.MapRazorPages();app.MapControllerRoute("default","{controller=Home}/{action=Index}/{id?}");app.Run();